from bisect import bisect_right

def num_digits_less_than_n(digits: List[int], n: int) -> int:
    ans = 0
    factor = 1
    n_str = str(n)
    for i in range(len(n_str) - 1, -1, -1):
        ans += bisect_right(digits, int(n_str[i])) * factor
        factor *= len(digits)
    return ans

def kth_smallest_element_in_bst(root: TreeNode, k: int) -> int:
    def helper(node: TreeNode, k: int) -> int:
        if not node:
            return 0
        left_size = helper(node.left, k)
        if left_size >= k:
            return node.val
        else:
            return helper(node.right, k - left_size - 1)
    return helper(root, k)
