    std::map<int, std::vector<int>> columnTable;
    std::queue<std::pair<TreeNode*, int>> q;
    q.push({root, 0});

    while (!q.empty()) {
        TreeNode* curNode = q.front().first;
        int column = q.front().second;
        q.pop();

        if (curNode) {
            columnTable[column].push_back(curNode->val);
            q.push({curNode->left, column - 1});
