class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def sumEvenGrandparent(root, parent=None, grandparent=None):
    if not root:
        return 0
    sum = (grandparent and grandparent.val % 2 == 0) * root.val
    return sum + sumEvenGrandparent(root.left, root, parent) + sumEvenGrandparent(root.right, root, parent)

def sumEvenGrandchildren(root):
    result = []
    if not root:
        return result
    sum = 0
    grandparent = root.left
    while grandparent:
        if grandparent.val % 2 == 0:
            sum += root.val
        grandparent = grandparent.left
    result.append(sum)
    return result
